def save_fixture(fixture: Dict[str, Any], filepath: str) -> None:
    """Save a fixture to file (JSON or YAML based on extension)."""
    if filepath.endswith(".yaml") or filepath.endswith(".yml"):
        with open(filepath, "w") as f:
            yaml.dump(fixture, f, default_flow_style=False)
    else:
        with open(filepath, "w") as f:
            json.dump(fixture, f, indent=2)


def load_fixture(filepath: str) -> Dict[str, Any]:
    """Load a fixture from file."""
    with open(filepath, "r") as f:
        if filepath.endswith(".yaml") or filepath.endswith(".yml"):
            return yaml.safe_load(f)
        else:
            return json.load(f)


def create_standard_fixture(
    seed: int,
    node_count: int,
    fault_specs: List[FaultSpec],
    invariants: List[str] = None,
) -> Dict[str, Any]:
    """Create a standard fixture from fault specs."""
    return {
        "seed": seed,
        "nodes": [{"id": f"node_{i}", "config": {}} for i in range(node_count)],
        "fault_schedule": [spec.to_dict() for spec in fault_specs],
        "invariants": invariants or [],
    }